import numpy as np


def q_learning_target(
    reward: float,
    next_q_values: np.ndarray,
    gamma: float,
    *,
    terminated: bool,
) -> float:
    if terminated:
        return float(reward)
    q_next = np.asarray(next_q_values, dtype=float)
    if q_next.ndim != 1 or q_next.size == 0:
        raise ValueError("next_q_values must be a non-empty vector")
    return float(reward + gamma * np.max(q_next))


def sarsa_target(
    reward: float,
    next_q_values: np.ndarray,
    next_action: int,
    gamma: float,
    *,
    terminated: bool,
) -> float:
    if terminated:
        return float(reward)
    q_next = np.asarray(next_q_values, dtype=float)
    if q_next.ndim != 1 or not 0 <= next_action < q_next.size:
        raise ValueError("invalid next-action value")
    return float(reward + gamma * q_next[next_action])
```

Различие действительно помещается в одну строку кода, но эта строка задаёт разные целевые политики. В полноценной SARSA-реализации `next_action` должен быть выбран той же политикой поведения, которая будет действовать дальше.

