import numpy as np


def double_q_target(
    reward: float,
    selector_q: np.ndarray,
    evaluator_q: np.ndarray,
    gamma: float,
    *,
    terminated: bool,
) -> float:
    if terminated:
        return float(reward)
    selector = np.asarray(selector_q, dtype=float)
    evaluator = np.asarray(evaluator_q, dtype=float)
    if selector.ndim != 1 or evaluator.shape != selector.shape:
        raise ValueError("selector_q and evaluator_q must be equal-length vectors")
    if selector.size == 0:
        raise ValueError("Q vectors must be non-empty")
    selected = int(np.argmax(selector))
    return float(reward + gamma * evaluator[selected])
```

Важно не брать `np.max(evaluator)`: тогда вторая таблица снова выбирала бы собственное действие. Double Q-learning требует оценить именно индекс, выбранный первой таблицей.
